-- 1) platform_settings: 'order.auto_complete_days' = 7
--    Source: ER_NOTES 'Order completion (v3)' + CHANGELOG_V3_TH.md (แนะนำ platform_settings order.auto_complete_days = 7)
--    authz: is_admin_editable = true (allowlist ของ PLATFORM_SETTING_UPDATE) + value_schema; setting_value เดิมไม่ถูกเขียนทับ
INSERT INTO platform_settings (setting_key, setting_value, is_admin_editable, value_schema, description)
VALUES ('order.auto_complete_days', '7'::jsonb, true, '{"type": "integer", "minimum": 1, "maximum": 30}'::jsonb,
        'จำนวนวันหลัง DELIVERED ที่ระบบปิดออเดอร์เป็น COMPLETED อัตโนมัติ')
ON CONFLICT (setting_key) DO UPDATE SET is_admin_editable = EXCLUDED.is_admin_editable, value_schema = EXCLUDED.value_schema,
    description = EXCLUDED.description
WHERE (platform_settings.is_admin_editable, platform_settings.value_schema, platform_settings.description)
      IS DISTINCT FROM (EXCLUDED.is_admin_editable, EXCLUDED.value_schema, EXCLUDED.description);

-- 2) platform_roles: PLATFORM_ADMIN (the only value in Enums_Status 'platform_role').
--    platform_roles.user_id is NOT NULL → needs an existing user. Optional: set email once in this session, then re-run:
--      SELECT set_config('app.admin_email', 'admin@example.com', false);
--    Without that setting, this step is skipped (no user is invented). Works in pgAdmin / DBeaver / psql.
DO $seed_admin$
DECLARE
  v_email   text := nullif(btrim(current_setting('app.admin_email', true)), '');
  v_user_id uuid;
BEGIN
  IF v_email IS NULL THEN
    RAISE NOTICE 'platform_roles: skipped (run SELECT set_config(''app.admin_email'', ''you@example.com'', false); then re-run this script)';
    RETURN;
  END IF;
  SELECT id INTO v_user_id FROM users WHERE email = v_email;
  IF v_user_id IS NULL THEN
    RAISE WARNING 'platform_roles: user % not found — nothing inserted', v_email;
    RETURN;
  END IF;
  INSERT INTO platform_roles (user_id, role, grant_reason)
  VALUES (v_user_id, 'PLATFORM_ADMIN', 'seed_reference_data.sql')
  ON CONFLICT (user_id) WHERE revoked_at IS NULL DO NOTHING;   -- partial unique uq_platform_roles_user_id_active
  RAISE NOTICE 'platform_roles: PLATFORM_ADMIN ensured for %', v_email;
END
$seed_admin$;

