    DELETE FROM auth_role_permissions arp
     USING auth_roles r, auth_permissions p
     WHERE arp.role_id = r.id AND arp.permission_id = p.id
       AND NOT EXISTS (SELECT 1 FROM v WHERE v.role_code = r.code AND v.perm_code = p.code)
       AND r.policy_version <> 'CUSTOM'
)
INSERT INTO auth_role_permissions (role_id, permission_id, policy_version)
SELECT r.id, p.id, '1.0' FROM v
  JOIN auth_roles r ON r.code = v.role_code
  JOIN auth_permissions p ON p.code = v.perm_code
ON CONFLICT (role_id, permission_id) DO NOTHING;
